(function(){'use strict';
/* JAH The Organic Chemistry generator — jahdb-organic-chemistry-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed, same record. */
var PREFIX='JAH-ORGCH-';
var FIELDS=["Foundations","Compounded","Advanced"];
var TOPICS=[{"tier": "Foundations", "g": "Fundamentals", "title": "What Is Organic Chemistry", "desc": "Organic chemistry is the study of carbon-containing compounds and their reactions. Carbon's ability to form four strong covalent bonds - to itself and to hydrogen, oxygen, nitrogen, halogens, and more - produces more known compounds than all other elements combined, from fuels and plastics to drugs and DNA.\nThe field divides into structure (what molecules look like), reactivity (how they change), and synthesis (how to build them). Its language is the structural formula: every line, wedge, and arrow carries meaning, and fluency in that language is the entry ticket to biochemistry, medicinal chemistry, and materials science.", "how": "Chemists represent molecules with structural formulas showing atom connectivity, then classify compounds by functional group - the reactive part of the molecule. Reactivity is predicted from electron distribution: electron-rich regions attack electron-poor ones. Reactions are drawn with curved arrows tracking electron pairs, and mechanisms are tested against kinetics, stereochemistry, and isotopic labeling.", "keys": ["Organic chemistry studies carbon compounds - the most numerous class of molecules known.", "Carbon forms four covalent bonds, enabling chains, rings, and complex architectures.", "The functional group determines a molecule's characteristic reactivity.", "Curved-arrow notation tracks electron flow in every mechanism.", "Structure, reactivity, and synthesis are the field's three pillars."], "reqs": ["Structural formulas showing atom connectivity.", "Functional-group vocabulary for classification.", "Electron-pair bookkeeping for mechanisms."], "stds": ["IUPAC nomenclature for naming compounds.", "Curved-arrow conventions for electron movement."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Clayden J, Greeves N, Warren S. Organic Chemistry. 2nd ed. Oxford; 2012."], "demo": "#!/usr/bin/env python3\n\"\"\"Count atoms in a molecular formula string.\"\"\"\nimport re\nformula = \"C6H12O6\"\natoms = {el: int(n or 1) for el, n in re.findall(r\"([A-Z][a-z]?)(\\d*)\", formula)}\nprint(\"formula:\", formula)\nfor el, n in atoms.items():\n    print(f\"  {el}: {n}\")\nprint(\"total atoms:\", sum(atoms.values()))\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "Carbon's Bonding Toolkit", "desc": "Carbon's versatility comes from hybridization: mixing one 2s and three 2p orbitals gives four sp3 orbitals in a tetrahedron (109.5 degrees), as in methane. Mixing 2s with two 2p gives three sp2 orbitals in a plane plus one p orbital for pi bonding, as in ethene; sp gives two linear orbitals plus two pi bonds, as in ethyne.\nSigma bonds form by head-on orbital overlap and allow rotation; pi bonds form by sideways p-orbital overlap and lock geometry. Bond length shortens and strength rises from single to double to triple, and the hybridization of carbon predicts molecular shape through VSEPR reasoning.", "how": "Count regions of electron density around carbon to assign hybridization: four regions means sp3, three means sp2, two means sp. Draw the sigma framework first, then add pi bonds between unhybridized p orbitals. Bond angles follow from geometry - tetrahedral, trigonal planar, or linear - and deviations reveal strain or electronic effects.", "keys": ["sp3 carbon is tetrahedral (109.5 deg); sp2 is trigonal planar (120 deg); sp is linear (180 deg).", "Sigma bonds allow rotation; pi bonds restrict it.", "Bond strength increases single < double < triple; length decreases.", "Hybridization is assigned by counting electron-density regions.", "VSEPR predicts molecular shape from electron-pair repulsion."], "reqs": ["Orbital-overlap picture of bonding.", "Electron-domain count per carbon.", "Measured bond angles for reference."], "stds": ["Bond lengths reported in angstroms or picometers.", "Angles reported in degrees with hybridization stated."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Fleming I. Molecular Orbitals and Organic Chemical Reactions. Wiley; 2009."], "demo": "#!/usr/bin/env python3\n\"\"\"Assign hybridization from electron-domain count.\"\"\"\ndef hybridization(domains):\n    return {4: \"sp3 tetrahedral 109.5 deg\", 3: \"sp2 trigonal planar 120 deg\", 2: \"sp linear 180 deg\"}.get(domains, \"unknown\")\nfor d in (4, 3, 2):\n    print(f\"  {d} domains -> {hybridization(d)}\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "Drawing Molecules: Lewis, Line-Angle, Condensed", "desc": "Chemists draw molecules in shorthands. Lewis structures show every atom and bond with dots for lone pairs. Condensed formulas compress them (CH3CH2OH). Line-angle (skeletal) formulas - the working language - draw carbon chains as zigzags where each vertex is a CH2/CH3 group and heteroatoms are labeled explicitly.\nFluency means converting between these instantly and reading a skeletal drawing as a full 3D molecule: counting hydrogens on each carbon, spotting functional groups, and seeing stereochemistry in wedges and dashes. Every mechanism in the field is drawn in line-angle form.", "how": "To read a line-angle structure, place a carbon at each vertex and line end, then add enough hydrogens to give each carbon four bonds. Wedges come out of the plane, dashes go back. Convert to Lewis by expanding each carbon with its hydrogens and lone pairs; condense by grouping CH3, CH2, and CH units along the chain.", "keys": ["Line-angle: vertices and ends are carbons; hydrogens are implied.", "Each carbon gets enough implied H to reach four bonds.", "Wedges project forward; dashes recede - the 3D code.", "Condensed formulas group repeated CHn units.", "Lewis structures show all atoms, bonds, and lone pairs."], "reqs": ["A drawn structure in any of the three notations.", "Heteroatom labels preserved in skeletal form.", "Stereochemical wedges where configuration matters."], "stds": ["Skeletal drawings per IUPAC graphical conventions.", "Wedge/dash notation for stereocenters."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Smith JG. Organic Chemistry. 6th ed. McGraw-Hill; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Expand a condensed formula into an atom count.\"\"\"\nimport re\ncondensed = \"CH3CH2CH2OH\"\nparts = re.findall(r\"[A-Z][a-z]?\\d*\", condensed)\ncounts = {}\nfor p in parts:\n    m = re.match(r\"([A-Z][a-z]?)(\\d*)\", p)\n    counts[m.group(1)] = counts.get(m.group(1), 0) + int(m.group(2) or 1)\nprint(condensed, \"->\", counts)\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "Functional Groups Overview", "desc": "A functional group is an atom or group of atoms with characteristic reactivity: alkenes, alkynes, alcohols, ethers, aldehydes, ketones, carboxylic acids, esters, amides, amines, alkyl halides, and aromatics. Recognizing them lets a chemist predict behavior - an alcohol can be oxidized, a carboxylic acid is acidic, an alkene adds bromine.\nPriority order matters for naming: carboxylic acids outrank aldehydes, which outrank ketones, alcohols, and amines. The same molecule can carry several groups, and synthesis is largely the art of transforming one group into another while leaving the rest untouched.", "how": "Scan a structure for heteroatoms and pi bonds, then match each to the functional-group catalog. Assign the highest-priority group as the suffix in the IUPAC name and others as prefixes. Predict reactivity from the group's polarity and electron distribution: nucleophilic sites attack electrophilic ones.", "keys": ["Functional groups are the reactive units that define chemical behavior.", "Priority order decides naming suffix vs prefix.", "Heteroatoms (O, N, X) usually mark the functional group.", "One molecule can carry several groups with independent reactivity.", "Synthesis = converting one functional group into another."], "reqs": ["Catalog of group structures and names.", "IUPAC priority ranking.", "Polarity map of each group."], "stds": ["IUPAC substitutive nomenclature.", "Group names per IUPAC recommendations."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Bruice PY. Organic Chemistry. 8th ed. Pearson; 2020."], "demo": "#!/usr/bin/env python3\n\"\"\"Identify a functional group from a SMILES-like tag.\"\"\"\nGROUPS = {\"C=C\": \"alkene\", \"C#C\": \"alkyne\", \"-OH\": \"alcohol\", \"C=O\": \"carbonyl\", \"COOH\": \"carboxylic acid\", \"NH2\": \"amine\"}\nfor tag in [\"C=C\", \"-OH\", \"COOH\", \"NH2\"]:\n    print(f\"  {tag:6s} -> {GROUPS[tag]}\")\n"}, {"tier": "Foundations", "g": "Hydrocarbons", "title": "Alkanes: Structure and Nomenclature", "desc": "Alkanes are saturated hydrocarbons - single bonds only, formula CnH2n+2. Methane, ethane, propane, butane begin the series; longer chains, branched isomers, and cycloalkanes extend it. They are the fuels of civilization: natural gas is mostly methane, gasoline is C5-C12 alkanes.\nIUPAC naming finds the longest carbon chain, numbers to give substituents the lowest locants, and lists substituents alphabetically: 2-methylbutane, not 3-methylbutane. Conformations - staggered vs eclipsed, visualized in Newman projections - explain why some shapes are lower in energy.", "how": "Name an alkane: identify the longest continuous chain as the parent, number from the end nearest a substituent, name substituents as alkyl prefixes with locants, and assemble alphabetically. Draw conformers with Newman projections looking down a C-C bond; staggered conformations minimize torsional strain.", "keys": ["Alkanes: CnH2n+2, single bonds only, the fuel family.", "Longest chain is the parent; lowest locants win.", "Substituents listed alphabetically with position numbers.", "Staggered conformations are lower in energy than eclipsed.", "Cycloalkanes add ring strain (worst at cyclopropane)."], "reqs": ["Full carbon skeleton of the molecule.", "Correct longest-chain identification.", "Newman projection for conformers."], "stds": ["IUPAC alkane nomenclature (1979/2013 recommendations).", "Locant numbering giving lowest set."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Solomons TWG, Fryhle CB. Organic Chemistry. 12th ed. Wiley; 2016."], "demo": "#!/usr/bin/env python3\n\"\"\"Alkane formula CnH2n+2 and molar mass.\"\"\"\ndef alkane(n):\n    c, h = n, 2*n+2\n    mass = c*12.011 + h*1.008\n    return c, h, mass\nfor n in (1, 4, 8):\n    c, h, mass = alkane(n)\n    print(f\"  C{c}H{h}: {mass:.2f} g/mol\")\n"}, {"tier": "Foundations", "g": "Hydrocarbons", "title": "Alkenes and Alkynes: Multiple Bonds", "desc": "Alkenes carry a C=C double bond (CnH2n); alkynes a C≡C triple bond (CnH2n-2). The pi bond is weaker and more exposed than the sigma framework, making multiple bonds the reactive sites: they add reagents across the bond, and the geometry is locked - no rotation about C=C.\nLocked geometry creates cis/trans (E/Z) isomerism: substituents fixed on the same or opposite sides. Naming adds -ene or -yne with a locant for the multiple bond's position. Ethene ripens fruit; ethyne (acetylene) fuels welding torches at 3300 C.", "how": "Assign E/Z by ranking substituents on each carbon with Cahn-Ingold-Prelog priorities: highest-priority groups on the same side is Z (zusammen), opposite is E (entgegen). Number the chain to give the multiple bond the lowest locant. Predict addition reactivity from the pi bond's exposed electron density.", "keys": ["Alkenes: C=C; alkynes: triple bond - pi bonds are the reactive sites.", "No rotation about C=C locks cis/trans (E/Z) geometry.", "E/Z assigned by Cahn-Ingold-Prelog priority ranking.", "Suffixes -ene / -yne with locants name them.", "Pi electrons make multiple bonds nucleophilic."], "reqs": ["CIP priority ranking of substituents.", "Lowest locant for the multiple bond.", "Wedge/dash or E/Z label for geometry."], "stds": ["E/Z notation per Cahn-Ingold-Prelog rules.", "IUPAC -ene/-yne nomenclature."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Clayden J, Greeves N, Warren S. Organic Chemistry. 2nd ed. Oxford; 2012."], "demo": "#!/usr/bin/env python3\n\"\"\"Degree of unsaturation from a molecular formula.\"\"\"\ndef dou(c, h, n=0, x=0):\n    return (2*c + 2 + n - h - x)//2\nfor f in [(\"C6H14\",6,14),(\"C6H12\",6,12),(\"C6H10\",6,10),(\"C6H6\",6,6)]:\n    print(f\"  {f[0]}: DoU = {dou(f[1],f[2])}\")\n"}, {"tier": "Foundations", "g": "Stereochemistry", "title": "Isomerism: Constitutional and Stereoisomers", "desc": "Isomers share a molecular formula but differ in arrangement. Constitutional isomers differ in connectivity - butane vs methylpropane. Stereoisomers share connectivity but differ in 3D arrangement: cis/trans isomers and enantiomers/diastereomers.\nThe distinction matters enormously: constitutional isomers can have wildly different boiling points, while enantiomers - mirror images - can smell, taste, or heal differently. Thalidomide's tragedy is the classic warning that stereochemistry is pharmacology.", "how": "First check connectivity: different bonding means constitutional isomers. If connectivity matches, look for stereoisomerism - restricted rotation (E/Z) or tetrahedral stereocenters (R/S). Enantiomers are non-superimposable mirror images; diastereomers are stereoisomers that are not mirror images and differ in physical properties.", "keys": ["Same formula, different arrangement = isomers.", "Constitutional: different connectivity.", "Stereoisomers: same connectivity, different 3D arrangement.", "Enantiomers are mirror images; diastereomers are not.", "Stereochemistry can decide biological activity."], "reqs": ["Molecular formula confirmed identical.", "Connectivity map for each candidate.", "3D arrangement at each stereoelement."], "stds": ["IUPAC stereodescriptors (E/Z, R/S, cis/trans).", "Fischer and wedge-dash drawing conventions."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Eliel EL, Wilen SH. Stereochemistry of Organic Compounds. Wiley; 1994."], "demo": "#!/usr/bin/env python3\n\"\"\"List isomer classes for a formula pair.\"\"\"\npairs = [(\"butane\",\"methylpropane\",\"constitutional\"),(\"cis-2-butene\",\"trans-2-butene\",\"diastereomers\"),(\"(R)-lactic acid\",\"(S)-lactic acid\",\"enantiomers\")]\nfor a, b, kind in pairs:\n    print(f\"  {a} vs {b}: {kind}\")\n"}, {"tier": "Foundations", "g": "Stereochemistry", "title": "Chirality and Enantiomers", "desc": "A molecule is chiral if it cannot be superimposed on its mirror image - like left and right hands. The common cause is a carbon with four different substituents, a stereocenter. Its two enantiomers rotate plane-polarized light in opposite directions and interact differently with other chiral environments.\nLiving systems are chiral selectors: enzymes, receptors, and transporters usually bind one enantiomer. R/S assignment via Cahn-Ingold-Prelog rules gives each stereocenter an absolute configuration, and a molecule's full stereochemistry is part of its identity.", "how": "Assign R/S: rank the four substituents by CIP priority, orient the lowest priority away, and trace 1→2→3. Clockwise is R (rectus), counterclockwise is S (sinister). Check for internal mirror planes - meso compounds have stereocenters but are achiral overall. Measure optical activity with a polarimeter as [alpha]D.", "keys": ["Chirality = non-superimposable mirror image.", "A carbon with four different groups is a stereocenter.", "Enantiomers rotate polarized light oppositely.", "R/S assigned by CIP priorities traced 1-2-3.", "Meso compounds have stereocenters but are achiral."], "reqs": ["Four distinct substituents identified.", "CIP ranking completed.", "Meso check for symmetry planes."], "stds": ["Cahn-Ingold-Prelog R/S assignment.", "Specific rotation [alpha]D reporting."], "cites": ["Eliel EL, Wilen SH. Stereochemistry of Organic Compounds. Wiley; 1994.", "McMurry J. Organic Chemistry. 10th ed. Cengage; 2023."], "demo": "#!/usr/bin/env python3\n\"\"\"R/S assignment from an ordered substituent list.\"\"\"\ndef assign(order):\n    # order: priorities 1,2,3 traced with 4 in back; clockwise=True -> R\n    return \"R\" if order == \"clockwise\" else \"S\"\nfor o in (\"clockwise\", \"counterclockwise\"):\n    print(f\"  1->2->3 {o}: {assign(o)}\")\n"}, {"tier": "Foundations", "g": "Reactivity", "title": "Acids, Bases, and pKa in Organic Reactions", "desc": "Bronsted acids donate protons; bases accept them. The pKa scale quantifies strength: lower pKa means stronger acid, and equilibrium favors the side with the weaker acid (higher pKa). A difference of 5 pKa units means essentially complete proton transfer.\nOrganic reactivity runs on this: carboxylic acids (pKa ~5) are deprotonated by bicarbonate, alcohols (pKa ~16) need stronger bases, and terminal alkynes (pKa ~25) need amide ion. Lewis acids (electron-pair acceptors like AlCl3) and bases extend the picture to non-proton chemistry.", "how": "Predict proton-transfer direction: the equilibrium lies toward the weaker acid and weaker base. Estimate pKa from structure - resonance stabilization of the conjugate base lowers pKa (phenol ~10 vs ethanol ~16). Choose reagents by pKa ladder: a base deprotonates any acid with lower pKa, quantitatively if the gap exceeds ~3 units.", "keys": ["Lower pKa = stronger acid; equilibrium favors the weaker acid.", "pKa gap > 3 means essentially complete transfer.", "Resonance-stabilized conjugate bases are more acidic.", "Carboxylic acid ~5, phenol ~10, alcohol ~16, alkyne ~25.", "Lewis acids accept electron pairs (AlCl3, BF3)."], "reqs": ["pKa values for acids involved.", "Conjugate base stability assessment.", "Solvent noted (pKa is solvent-dependent)."], "stds": ["pKa reported with solvent (usually water or DMSO).", "Bronsted-Lowry definitions unless Lewis stated."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Evans P. pKa tables (Harvard)."], "demo": "#!/usr/bin/env python3\n\"\"\"Predict proton-transfer direction from pKa values.\"\"\"\ndef direction(pka_acid, pka_conj):\n    return \"favors products (weaker acid side)\" if pka_conj > pka_acid else \"favors reactants\"\nprint(\"  acetic acid (4.8) + OH- -> water (15.7):\", direction(4.8, 15.7))\nprint(\"  ethanol (16) + OH- -> water (15.7):\", direction(16, 15.7))\n"}, {"tier": "Foundations", "g": "Reactivity", "title": "Intermolecular Forces and Physical Properties", "desc": "Boiling points, solubility, and chromatography all trace to intermolecular forces: London dispersion (all molecules), dipole-dipole, and hydrogen bonding (H attached to N, O, or F). Ethanol boils at 78 C while dimethyl ether - same formula C2H6O - boils at -24 C, purely from hydrogen bonding.\n'Like dissolves like': polar protic solvents dissolve ions, nonpolar solvents dissolve hydrocarbons. Chromatography separates by differential attraction to stationary vs mobile phases - the same forces, exploited analytically.", "how": "Rank boiling points: hydrogen bonding > dipole-dipole > dispersion at similar mass; larger surface area raises dispersion forces. Predict solubility with 'like dissolves like' and hydrogen-bond donor/acceptor counts. In chromatography, stronger stationary-phase attraction means slower elution and larger retention.", "keys": ["H-bonding >> dipole-dipole > dispersion in strength.", "Same formula, different forces = very different boiling points.", "Like dissolves like governs solubility.", "Branching lowers boiling point (less surface contact).", "Chromatography exploits these forces for separation."], "reqs": ["Molecular weight and shape.", "H-bond donor/acceptor inventory.", "Dipole moment estimate."], "stds": ["Boiling points at stated pressure.", "Solubility in g/100 mL with solvent and temperature."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Israelachvili JN. Intermolecular and Surface Forces. 3rd ed. Academic Press; 2011."], "demo": "#!/usr/bin/env python3\n\"\"\"Rank boiling points by H-bonding and mass.\"\"\"\nmols = [(\"dimethyl ether\", -24, False), (\"ethanol\", 78, True), (\"propane\", -42, False)]\nfor name, bp, hb in sorted(mols, key=lambda m: m[1]):\n    print(f\"  {name:16s} bp {bp:4d} C  H-bonding: {hb}\")\n"}, {"tier": "Foundations", "g": "Reactivity", "title": "Resonance and Delocalization", "desc": "Some molecules cannot be drawn with a single Lewis structure: benzene's pi electrons, the carboxylate anion, the allyl cation. Resonance structures differ only in electron positions, and the true molecule is a hybrid - lower in energy than any single contributor by the resonance energy.\nRules: never move atoms, only pi electrons and lone pairs; keep octets; minimize charge separation; negative charge belongs on the most electronegative atom. Resonance explains acidity trends, color, and why benzene refuses addition reactions.", "how": "Draw resonance forms by pushing lone pairs or pi bonds toward adjacent pi systems or empty p orbitals, checking octets at each step. Rank contributors: full octets beat incomplete ones, and charge placement favors electronegativity. Use the hybrid to predict the real electron distribution - e.g., equal C-O bonds in carboxylate.", "keys": ["Resonance forms differ in electrons only - atoms never move.", "The hybrid is more stable than any contributor.", "Octets and minimal charge separation rank contributors.", "Delocalization explains acidity, color, and stability.", "Curved arrows push pi electrons and lone pairs."], "reqs": ["Valid Lewis structure as starting point.", "Adjacent pi system, lone pair, or empty p orbital.", "Octet check on every contributor."], "stds": ["Resonance arrow (<->) between contributors.", "Brackets with overall charge on the hybrid."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Wheland GW. Resonance in Organic Chemistry. Wiley; 1955."], "demo": "#!/usr/bin/env python3\n\"\"\"Count resonance contributors for simple pi systems.\"\"\"\nsystems = {\"allyl cation\": 2, \"carboxylate\": 2, \"benzene (Kekule)\": 2, \"carbonate\": 3}\nfor name, n in systems.items():\n    print(f\"  {name:18s}: {n} major contributors\")\n"}, {"tier": "Compounded", "g": "Reactions", "title": "Alkane Reactions: Combustion and Radical Halogenation", "desc": "Alkanes are famously unreactive - but they burn and they undergo radical halogenation. Combustion with O2 gives CO2 and H2O, releasing ~890 kJ/mol for methane: the energy basis of natural gas heating. Radical halogenation replaces a C-H with C-X via a chain mechanism.\nThe chain has three phases: initiation (homolysis of X2 by heat or light), propagation (X· abstracts H, then R· takes X from X2), and termination (radical couplings). Selectivity follows bond strength: tertiary C-H reacts fastest (3° > 2° > 1°), so bromination is highly selective while chlorination is not.", "how": "Run halogenation with Cl2/hv or Br2/hv; predict products by counting each type of hydrogen and weighting by relative reactivity (bromination ~ 1:80:1600 for 1°:2°:3°). Write the mechanism as initiation, two propagation steps, and termination. Balance combustion with the hydrocarbon + O2 -> CO2 + H2O template.", "keys": ["Alkanes react by combustion and radical substitution.", "Chain: initiation, propagation, termination.", "Reactivity 3° > 2° > 1° C-H bonds.", "Bromination is selective; chlorination gives mixtures.", "Light or heat initiates by homolyzing X2."], "reqs": ["X2 and hv or heat for initiation.", "Inventory of 1°/2°/3° hydrogens.", "Inert C-H framework otherwise."], "stds": ["Radical dots on single-electron species.", "Bond dissociation energies in kJ/mol."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Walling C. Free Radicals in Solution. Wiley; 1957."], "demo": "#!/usr/bin/env python3\n\"\"\"Predict radical bromination product distribution.\"\"\"\n# 2-methylpropane: 9 primary H, 1 tertiary H; rel rates 1 : 1600\ncounts = {\"1-bromo (primary)\": 9*1, \"2-bromo (tertiary)\": 1*1600}\ntotal = sum(counts.values())\nfor name, w in counts.items():\n    print(f\"  {name:22s}: {100*w/total:.1f}%\")\n"}, {"tier": "Compounded", "g": "Reactions", "title": "Alkene Addition Reactions", "desc": "The pi bond of an alkene is a nucleophile: electrophiles attack it, and the pair of new bonds forms across the double bond. HX adds by Markovnikov's rule - the proton goes to the carbon that already has more hydrogens, placing the more stable carbocation on the more substituted carbon.\nThe toolkit is large: acid-catalyzed hydration (Markovnikov alcohols), oxymercuration (no rearrangement), hydroboration-oxidation (anti-Markovnikov alcohols), bromination (anti addition via bromonium ion), halohydrin formation, epoxidation, ozonolysis (cleavage), catalytic hydrogenation, and dihydroxylation. Each has its own regio- and stereochemistry.", "how": "Choose conditions by target: Markovnikov vs anti-Markovnikov, syn vs anti. Draw the mechanism - carbocation, bridged ion, or concerted cyclic transition state - and assign stereochemistry: bromonium ions open anti, hydroboration adds syn. For hydration without rearrangement, use oxymercuration-demercuration.", "keys": ["Pi bond acts as nucleophile toward electrophiles.", "Markovnikov: H to the less substituted carbon.", "Bromonium ion forces anti addition.", "Hydroboration-oxidation gives anti-Markovnikov syn alcohols.", "Ozonolysis cleaves the double bond entirely."], "reqs": ["Alkene substrate with defined substitution.", "Reagent matched to desired regio/stereochemistry.", "Carbocation rearrangement check."], "stds": ["Markovnikov/anti-Markovnikov labels stated.", "Syn/anti stereochemistry specified."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Brown HC. Hydroboration. Benjamin; 1962."], "demo": "#!/usr/bin/env python3\n\"\"\"Markovnikov predictor for HX addition.\"\"\"\ndef markovnikov(alkene):\n    # toy model: proton adds to carbon with more H\n    table = {\"propene\": \"2-halopropane\", \"1-butene\": \"2-halobutane\", \"2-butene\": \"2-halobutane\"}\n    return table.get(alkene, \"unknown\")\nfor a in (\"propene\", \"1-butene\", \"2-butene\"):\n    print(f\"  {a} + HX -> {markovnikov(a)}\")\n"}, {"tier": "Compounded", "g": "Reactions", "title": "Alkyne Reactions", "desc": "Alkynes undergo addition like alkenes but twice: two equivalents of HX or X2 add, and controlled conditions stop at the alkene stage. Catalytic hydrogenation with Lindlar's catalyst gives cis-alkenes; dissolving-metal reduction (Na/NH3) gives trans-alkenes - stereocontrolled routes to either geometry.\nHydration follows Markovnikov's rule with Hg2+ catalysis to give methyl ketones (or aldehydes from terminal alkynes under hydroboration). The terminal alkyne C-H (pKa ~25) is acidic enough for deprotonation by NaNH2, and the resulting acetylide anion is a carbon nucleophile for C-C bond formation.", "how": "Reduce selectively: Lindlar for cis, Na/NH3 for trans, excess H2/Pt for the alkane. Alkylate terminal alkynes by deprotonating with NaNH2 then SN2 with a primary alkyl halide - building carbon skeletons two carbons at a time. Hydrate with HgSO4/H2SO4 for Markovnikov ketones.", "keys": ["Two addition equivalents possible; conditions control stopping point.", "Lindlar gives cis-alkenes; Na/NH3 gives trans-alkenes.", "Terminal alkynes deprotonated by strong base (pKa ~25).", "Acetylide anions alkylate to extend carbon chains.", "Hg2+-catalyzed hydration gives methyl ketones."], "reqs": ["Alkyne substitution pattern known.", "Poisoned vs full catalyst chosen deliberately.", "Strong base for terminal deprotonation."], "stds": ["Cis/trans labels on reduction products.", "pKa ~25 cited for terminal alkyne acidity."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Smith JG. Organic Chemistry. 6th ed. McGraw-Hill; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Alkyne reduction outcome table.\"\"\"\ntable = {\"Lindlar Pd/H2\": \"cis-alkene\", \"Na / NH3(l)\": \"trans-alkene\", \"excess H2/Pt\": \"alkane\"}\nfor cond, prod in table.items():\n    print(f\"  {cond:16s} -> {prod}\")\n"}, {"tier": "Compounded", "g": "Mechanisms", "title": "SN1 and SN2 Substitution", "desc": "Nucleophilic substitution replaces a leaving group with a nucleophile. SN2 is concerted: the nucleophile attacks from the back side as the leaving group departs, inverting configuration (Walden inversion), with rate = k[RX][Nu]. Methyl and primary substrates react fastest.\nSN1 is stepwise: the leaving group leaves first, forming a planar carbocation that the nucleophile attacks from either face (racemization), with rate = k[RX]. Tertiary substrates ionize fastest, and carbocations can rearrange. Solvent decides: polar protic favors SN1, polar aprotic favors SN2.", "how": "Classify the substrate (methyl/1°/2°/3°), nucleophile strength, leaving group ability, and solvent. SN2: strong nucleophile + 1° substrate + polar aprotic solvent (DMSO, acetone). SN1: 3° substrate + weak nucleophile + polar protic solvent. Predict stereochemistry: inversion for SN2, racemization for SN1.", "keys": ["SN2: concerted, back-side attack, inversion, 2nd-order kinetics.", "SN1: carbocation intermediate, racemization, 1st-order kinetics.", "Substrate: SN2 loves 1°, SN1 loves 3°.", "Polar aprotic boosts SN2; polar protic boosts SN1.", "Carbocations rearrange in SN1 - watch for hydride shifts."], "reqs": ["Substrate class and leaving group identified.", "Nucleophile strength ranked.", "Solvent polarity/proticity noted."], "stds": ["Rate laws written as rate = k[RX][Nu] or k[RX].", "Inversion/racemization stated explicitly."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Ingold CK. Structure and Mechanism in Organic Chemistry. 2nd ed. Cornell; 1969."], "demo": "#!/usr/bin/env python3\n\"\"\"SN1 vs SN2 predictor from substrate class.\"\"\"\ndef pathway(sub):\n    return {\"methyl\": \"SN2 fast\", \"primary\": \"SN2\", \"secondary\": \"SN1/SN2 borderline\", \"tertiary\": \"SN1\"}[sub]\nfor s in (\"methyl\", \"primary\", \"secondary\", \"tertiary\"):\n    print(f\"  {s:10s} -> {pathway(s)}\")\n"}, {"tier": "Compounded", "g": "Mechanisms", "title": "E1 and E2 Elimination", "desc": "Elimination removes HX to form an alkene. E2 is concerted: base abstracts a proton anti-periplanar to the leaving group while the C-X bond breaks, forming the C=C in one step. E1 goes through a carbocation first, then deprotonation - the same intermediate as SN1.\nZaitsev's rule: the more substituted (more stable) alkene predominates, unless a bulky base (t-BuOK) forces the Hofmann (less substituted) product. E2 needs the C-H and C-X bonds anti-periplanar - geometry is a requirement, not a preference. Substitution and elimination always compete.", "how": "Draw the substrate in a conformation with H and X anti-periplanar for E2. Apply Zaitsev with small bases, Hofmann with bulky bases. For E1, form the most stable carbocation, check rearrangements, then remove any adjacent proton - the most substituted alkene wins. Decide substitution vs elimination by base strength, bulk, and temperature (heat favors elimination).", "keys": ["E2: concerted, anti-periplanar geometry required.", "E1: carbocation intermediate, like SN1.", "Zaitsev: more substituted alkene usually wins.", "Bulky bases give the Hofmann (less substituted) product.", "Strong bulky base + heat = elimination over substitution."], "reqs": ["Beta-hydrogens available.", "Base size and strength specified.", "Anti-periplanar conformation accessible."], "stds": ["Zaitsev/Hofmann regiochemistry labeled.", "E/Z of alkene products assigned."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Saunders WH. The Chemistry of Alkenes. Wiley; 1964."], "demo": "#!/usr/bin/env python3\n\"\"\"Zaitsev vs Hofmann product predictor.\"\"\"\ndef elimination(base):\n    return \"Hofmann (less substituted)\" if \"t-BuOK\" in base else \"Zaitsev (more substituted)\"\nfor b in (\"KOH/EtOH\", \"t-BuOK/t-BuOH\"):\n    print(f\"  {b:14s} -> {elimination(b)}\")\n"}, {"tier": "Compounded", "g": "Functional Groups", "title": "Alcohols: Properties and Reactions", "desc": "The -OH group makes alcohols polar, hydrogen-bonding, and higher-boiling than comparable alkanes. Methanol, ethanol, and isopropanol are the common solvents; ethanol is the intoxicant and fuel additive. Classification as 1°, 2°, or 3° (by carbons attached to the C-OH carbon) predicts reactivity.\nKey reactions: conversion to alkyl halides (SOCl2, PBr3 - SN2, no rearrangement), dehydration to alkenes (acid, Zaitsev), and oxidation - PCC stops at aldehydes for 1° alcohols, Jones/CrO3 goes to carboxylic acids, 2° alcohols give ketones, 3° alcohols resist oxidation entirely.", "how": "Classify the alcohol first - oxidation outcome depends on it. For substitution without rearrangement use SOCl2 (Cl) or PBr3 (Br). Dehydrate with concentrated H2SO4 and heat, predicting the Zaitsev alkene. Oxidize deliberately: PCC for aldehyde, CrO3/H2SO4 for acid, Na2Cr2O7 for ketones from 2° alcohols.", "keys": ["1°/2°/3° classification predicts oxidation behavior.", "SOCl2/PBr3 convert OH to halide cleanly (SN2).", "PCC: 1° alcohol -> aldehyde; Jones: -> carboxylic acid.", "2° -> ketone; 3° resists oxidation.", "Acid + heat dehydrates to the Zaitsev alkene."], "reqs": ["Alcohol class identified.", "Oxidant matched to target oxidation state.", "Acid-sensitive groups flagged before dehydration."], "stds": ["PCC vs Jones reagent outcomes distinguished.", "Oxidation states tracked on carbon."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Smith MB. Organic Synthesis. 4th ed. Academic Press; 2016."], "demo": "#!/usr/bin/env python3\n\"\"\"Alcohol oxidation outcome table.\"\"\"\ntable = {(\"primary\", \"PCC\"): \"aldehyde\", (\"primary\", \"CrO3/H2SO4\"): \"carboxylic acid\", (\"secondary\", \"any\"): \"ketone\", (\"tertiary\", \"any\"): \"no reaction\"}\nfor (cls, ox), prod in table.items():\n    print(f\"  {cls:10s} + {ox:12s} -> {prod}\")\n"}, {"tier": "Compounded", "g": "Functional Groups", "title": "Ethers and Epoxides", "desc": "Ethers (R-O-R) are polar but cannot hydrogen-bond to themselves, giving low boiling points and superb solvent properties - diethyl ether and THF are the classic reaction media. They are cleaved by strong acids (HI, HBr) via SN1/SN2 depending on substitution.\nEpoxides are three-membered cyclic ethers with ~115 kJ/mol of ring strain, making them spring-loaded electrophiles. Nucleophiles open them: under basic conditions at the less hindered carbon, under acidic conditions at the more substituted carbon. Epoxidation of alkenes with mCPBA is syn and stereospecific.", "how": "Use ethers as inert solvents but remember acid cleavage (HI gives alkyl iodides). Open epoxides with the regiochemistry rule: base/nucleophile attacks less hindered carbon; acid protonates oxygen first, then nucleophile attacks the more substituted carbon. Make epoxides from alkenes with mCPBA, preserving alkene stereochemistry in the epoxide.", "keys": ["Ethers: excellent solvents, cleaved by HI/HBr.", "Epoxide ring strain drives ring-opening reactions.", "Base: attack less hindered carbon; acid: more substituted.", "mCPBA epoxidation is syn and stereospecific.", "Ethers resist bases and nucleophiles - useful protecting groups."], "reqs": ["Ether substitution pattern for cleavage mode.", "Acidic vs basic opening conditions.", "Alkene geometry for epoxidation stereochemistry."], "stds": ["Epoxide stereochemistry drawn with wedges.", "Regiochemistry rule stated per conditions."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Smith JG. Organic Chemistry. 6th ed. McGraw-Hill; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Epoxide opening regiochemistry.\"\"\"\ndef opening(conditions):\n    return \"attack less-hindered C\" if conditions == \"basic\" else \"attack more-substituted C\"\nfor c in (\"basic\", \"acidic\"):\n    print(f\"  {c:7s} conditions -> {opening(c)}\")\n"}, {"tier": "Compounded", "g": "Functional Groups", "title": "Aldehydes and Ketones: Carbonyl Basics", "desc": "The C=O bond is strongly polarized (Cδ+, Oδ-), making the carbonyl carbon electrophilic. Aldehydes (R-CHO) have one hydrogen on the carbonyl carbon; ketones (R-CO-R) have two carbons. Aldehydes oxidize easily (Tollens test); ketones do not.\nNucleophilic addition is the characteristic reaction: Grignard reagents give alcohols, hydride (NaBH4, LiAlH4) gives alcohols, HCN gives cyanohydrins, and alcohols give hemiacetals/acetals under acid. Formaldehyde, acetaldehyde, and acetone are the industrial workhorses.", "how": "Attack the carbonyl carbon with nucleophiles; protonate oxygen under acidic conditions to activate. Protect aldehydes/ketones as acetals (ROH, H+) when other chemistry must proceed, and deprotect with aqueous acid. Distinguish aldehydes from ketones with Tollens or Fehling tests - aldehydes reduce Ag+ to a silver mirror.", "keys": ["C=O polarized: carbon is the electrophile.", "Nucleophilic addition is the signature reaction.", "Aldehydes oxidize; ketones resist (Tollens test).", "Acetals protect carbonyls, removed by aqueous acid.", "Grignard + carbonyl -> alcohol (C-C bond formed)."], "reqs": ["Aldehyde vs ketone identified.", "Nucleophile matched to target alcohol class.", "Acid/base catalysis as needed."], "stds": ["Tollens test for aldehyde identification.", "Acetal formation/deprotection conditions stated."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Clayden J, Greeves N, Warren S. Organic Chemistry. 2nd ed. Oxford; 2012."], "demo": "#!/usr/bin/env python3\n\"\"\"Carbonyl + nucleophile product predictor.\"\"\"\ntable = {(\"aldehyde\", \"RMgBr\"): \"secondary alcohol\", (\"ketone\", \"RMgBr\"): \"tertiary alcohol\", (\"aldehyde\", \"NaBH4\"): \"primary alcohol\", (\"ketone\", \"NaBH4\"): \"secondary alcohol\"}\nfor (carb, nu), prod in table.items():\n    print(f\"  {carb:9s} + {nu:6s} -> {prod}\")\n"}, {"tier": "Compounded", "g": "Functional Groups", "title": "Carboxylic Acids and Derivatives", "desc": "Carboxylic acids (R-COOH, pKa ~5) are the strongest common organic acids, deprotonated even by bicarbonate - the classic separation trick. Their derivatives - acyl chlorides, anhydrides, esters, amides - interconvert by nucleophilic acyl substitution down a reactivity ladder.\nReactivity order: acyl chloride > anhydride > aldehyde/ketone > ester > amide. More reactive derivatives convert to less reactive ones (acid chloride + amine -> amide); the reverse needs forcing. Fischer esterification (acid + alcohol, H+) is reversible; saponification (ester + OH-) is not.", "how": "Climb down the reactivity ladder freely; to go up, reactivate (SOCl2 makes acyl chlorides). Make esters by Fischer esterification with excess alcohol to drive equilibrium, or from acyl chlorides for hindered cases. Hydrolyze with aqueous acid or base; reduce esters to 1° alcohols with LiAlH4 (2 equiv).", "keys": ["Reactivity: acyl chloride > anhydride > ester > amide.", "Nucleophilic acyl substitution interconverts derivatives.", "Down the ladder is easy; up requires reactivation.", "Fischer esterification is reversible; saponification is not.", "LiAlH4 reduces esters to primary alcohols."], "reqs": ["Derivative class and its ladder position.", "Nucleophile and leaving-group ability.", "Equilibrium driving force for esterification."], "stds": ["Reactivity ladder cited in planning.", "Saponification vs acid hydrolysis distinguished."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Smith MB. Organic Synthesis. 4th ed. Academic Press; 2016."], "demo": "#!/usr/bin/env python3\n\"\"\"Acyl derivative reactivity ladder.\"\"\"\nladder = [\"acyl chloride\", \"anhydride\", \"ester\", \"amide\"]\nfor i, d in enumerate(ladder):\n    print(f\"  rank {i+1}: {d}\")\nprint(\"  conversion: down = easy, up = needs SOCl2\")\n"}, {"tier": "Compounded", "g": "Functional Groups", "title": "Amines: Structure and Basicity", "desc": "Amines (R-NH2, R2NH, R3N) are the organic bases, with a lone pair that accepts protons and attacks electrophiles. Basicity spans orders of magnitude: alkyl amines (conjugate acid pKa ~10-11) beat ammonia, while aryl amines like aniline (pKa ~4.6) are far weaker - the lone pair delocalizes into the ring.\nAmides are not basic at nitrogen (lone pair delocalized into C=O) - a classic trap. Amines form from alkyl halides + NH3 (overalkylation problem), Gabriel synthesis, reduction of nitro/nitriles/amides, and reductive amination of carbonyls - the cleanest route.", "how": "Predict basicity: alkyl > ammonia > aryl; electron-withdrawing groups lower it, donating groups raise it. Avoid overalkylation by using Gabriel synthesis or reductive amination instead of direct alkylation. Separate amines from neutrals by acid extraction: protonate with HCl, wash, then basify to recover.", "keys": ["Lone pair = basicity and nucleophilicity.", "Alkyl amines > ammonia > aryl amines in basicity.", "Amides are essentially nonbasic at nitrogen.", "Reductive amination is the cleanest amine synthesis.", "Acid extraction separates amines from neutral compounds."], "reqs": ["Amine class (1°/2°/3°, alkyl/aryl).", "Conjugate-acid pKa for basicity ranking.", "Overalkylation control in synthesis."], "stds": ["Conjugate acid pKa values cited.", "Gabriel synthesis for primary amines."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Smith JG. Organic Chemistry. 6th ed. McGraw-Hill; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Rank amine basicity by conjugate-acid pKa (higher = stronger base).\"\"\"\namines = [(\"diethylamine\", 11.0), (\"ammonia\", 9.3), (\"aniline\", 4.6), (\"acetamide\", -0.5)]\nfor name, pka in sorted(amines, key=lambda a: -a[1]):\n    print(f\"  {name:14s} pKaH {pka:5.1f}\")\n"}, {"tier": "Compounded", "g": "Aromatics", "title": "Aromaticity and Benzene", "desc": "Benzene's six pi electrons in a planar ring give extraordinary stability - ~150 kJ/mol resonance energy. Hückel's rule (4n+2 pi electrons in a planar cyclic conjugated system) predicts aromaticity: benzene, the cyclopentadienyl anion, and the tropylium cation qualify; cyclobutadiene (4n) is antiaromatic.\nAromatic compounds undergo substitution, not addition - addition would destroy the aromatic sextet. Benzene is a feedstock for styrene, phenol, and countless drugs; its derivatives are named with ortho/meta/para for disubstitution patterns.", "how": "Test aromaticity: cyclic, planar, fully conjugated, 4n+2 pi electrons. Count pi electrons carefully - lone pairs in p orbitals count (pyrrole's N pair) but sp2 lone pairs in the plane do not (pyridine's). Name disubstituted benzenes o-/m-/p-; expect substitution chemistry that preserves the ring's pi sextet.", "keys": ["Hückel 4n+2 rule defines aromaticity.", "Aromatic: cyclic, planar, conjugated, 4n+2 pi electrons.", "Benzene undergoes substitution, not addition.", "Resonance energy ~150 kJ/mol for benzene.", "o-/m-/p- name disubstituted benzenes."], "reqs": ["Planarity and conjugation verified.", "Pi-electron count (4n+2 test).", "Heteroatom lone-pair orbital check."], "stds": ["Hückel rule citation for aromaticity claims.", "o-/m-/p- nomenclature for disubstitution."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Hückel E. Z Phys 1931;70:204-286."], "demo": "#!/usr/bin/env python3\n\"\"\"Hückel 4n+2 aromaticity test.\"\"\"\ndef aromatic(pi):\n    return pi % 4 == 2\nfor name, pi in [(\"benzene\", 6), (\"cyclobutadiene\", 4), (\"cyclopentadienyl anion\", 6), (\"cyclooctatetraene\", 8)]:\n    print(f\"  {name:26s} pi={pi}: aromatic? {aromatic(pi)}\")\n"}, {"tier": "Compounded", "g": "Aromatics", "title": "Electrophilic Aromatic Substitution", "desc": "Benzene attacks electrophiles through its pi system, forming a resonance-stabilized arenium (sigma) intermediate, then losing a proton to restore aromaticity. Nitration (HNO3/H2SO4), sulfonation, halogenation (Br2/FeBr3), Friedel-Crafts alkylation (RCl/AlCl3), and acylation install the key groups.\nSubstituents direct the next one: activators (OH, NH2, alkyl) direct ortho/para; deactivators (NO2, C=O, CN) direct meta. Friedel-Crafts alkylation suffers carbocation rearrangements and polyalkylation - acylation followed by reduction is the workaround.", "how": "Generate the electrophile (NO2+ from HNO3/H2SO4, Br+ from Br2/FeBr3, R+ from RCl/AlCl3). Draw the arenium ion with delocalized positive charge, then deprotonate to restore aromaticity. Plan multi-step sequences with directing effects: install meta-directors early, and never Friedel-Crafts on deactivated rings.", "keys": ["Mechanism: pi attack -> arenium ion -> deprotonation.", "Activators: o/p directors; deactivators: meta directors.", "Nitration, sulfonation, halogenation, F-C alkylation/acylation.", "F-C alkylation rearranges; acylate then reduce instead.", "No F-C on strongly deactivated rings."], "reqs": ["Electrophile generation conditions.", "Directing effects of existing substituents.", "Ring activation level for F-C feasibility."], "stds": ["Arenium ion drawn with delocalized charge.", "o-/m-/p- product ratios where relevant."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Olah GA. Friedel-Crafts Chemistry. Wiley; 1973."], "demo": "#!/usr/bin/env python3\n\"\"\"Directing-effect predictor.\"\"\"\ntable = {\"-OH\": \"o/p activator\", \"-CH3\": \"o/p activator\", \"-NO2\": \"meta deactivator\", \"-COOH\": \"meta deactivator\", \"-Cl\": \"o/p deactivator\"}\nfor sub, eff in table.items():\n    print(f\"  {sub:6s} -> {eff}\")\n"}, {"tier": "Advanced", "g": "Mechanisms", "title": "Nucleophilic Acyl Substitution Mechanisms", "desc": "Acyl substitution proceeds by addition-elimination: the nucleophile adds to the carbonyl forming a tetrahedral intermediate, which collapses by expelling the leaving group. The intermediate's fate decides everything - a good leaving group departs; a poor one returns starting material.\nCatalysis matters: acid protonates the carbonyl (better electrophile); base deprotonates the nucleophile (better nucleophile). In ester hydrolysis the tetrahedral intermediate can expel either alkoxide or hydroxide - under basic conditions the carboxylate product pulls the equilibrium irreversibly.", "how": "Draw the tetrahedral intermediate explicitly, then evaluate leaving-group ability to predict collapse direction. Under acidic conditions protonate the carbonyl first; under basic conditions use the anionic nucleophile. For synthesis, convert poor leaving groups (OH) into good ones (Cl) with SOCl2 before substitution.", "keys": ["Addition-elimination via tetrahedral intermediate.", "Leaving-group ability decides collapse direction.", "Acid activates carbonyl; base activates nucleophile.", "Saponification is driven by carboxylate formation.", "Poor leaving groups are upgraded with SOCl2."], "reqs": ["Carbonyl electrophile and nucleophile identified.", "Leaving-group pKa comparison.", "Acid/base catalysis conditions."], "stds": ["Tetrahedral intermediate drawn in mechanisms.", "Leaving-group ability ranked by conjugate-acid pKa."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Jencks WP. Catalysis in Chemistry and Enzymology. McGraw-Hill; 1969."], "demo": "#!/usr/bin/env python3\n\"\"\"Leaving-group ranking by conjugate-acid pKa (lower = better LG).\"\"\"\nlgs = [(\"Cl-\", -7), (\"RCOO-\", 5), (\"RO-\", 16), (\"NH2-\", 35)]\nfor name, pka in sorted(lgs, key=lambda l: l[1]):\n    print(f\"  {name:8s} pKaH {pka:4d}  (better <-)\")\n"}, {"tier": "Advanced", "g": "Synthesis", "title": "Aldol Condensation", "desc": "Enolates - carbanions alpha to carbonyls - are the great C-C bond builders. Under base, an enolate attacks another carbonyl: the aldol addition gives a beta-hydroxy carbonyl, which dehydrates under heat to the conjugated enone (aldol condensation). Acetaldehyde dimerizes to crotonaldehyde by this route.\nControl is the challenge: mixed aldols need one non-enolizable partner (benzaldehyde, formaldehyde) or directed enolate formation with LDA at -78 C. The Claisen condensation is the ester version, giving beta-keto esters - the gateway to acetoacetic ester synthesis.", "how": "Form the enolate with base (NaOH for simple cases, LDA for kinetic control at -78 C). Add to the carbonyl electrophile, then dehydrate with heat to the enone. For crossed aldols, use one partner lacking alpha hydrogens; for Claisen, use alkoxide matching the ester to avoid transesterification.", "keys": ["Enolates attack carbonyls to build C-C bonds.", "Aldol addition -> dehydration = aldol condensation.", "LDA at -78 C gives kinetic enolate control.", "Crossed aldols need a non-enolizable partner.", "Claisen condensation is the ester analogue."], "reqs": ["Alpha-hydrogens on the enolate precursor.", "Base matched to selectivity needs.", "Dehydration conditions for condensation."], "stds": ["Enolate geometry (E/Z) noted where relevant.", "Kinetic vs thermodynamic control stated."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Carey FA, Sundberg RJ. Advanced Organic Chemistry. 5th ed. Springer; 2007."], "demo": "#!/usr/bin/env python3\n\"\"\"Aldol product atom balance check.\"\"\"\n# 2 acetaldehyde (C2H4O) -> aldol C4H8O2 -> crotonaldehyde C4H6O + H2O\nc, h, o = 2*2, 2*4, 2*1\nprint(f\"  2 x C2H4O = C{c}H{h}O{o} (aldol addition product)\")\nprint(f\"  minus H2O -> C{c}H{h-2}O{o-1} (condensation product)\")\n"}, {"tier": "Advanced", "g": "Synthesis", "title": "Organometallic Reagents: Grignard and Organolithium", "desc": "Grignard reagents (RMgBr) and organolithiums (RLi) are carbon nucleophiles - the polarity of C-X is inverted (umpolung) to Cδ-. Made from alkyl halides and Mg or Li in dry ether, they attack carbonyls, epoxides, CO2, and nitriles to forge C-C bonds.\nThey are brutally basic and water-intolerant: any O-H, N-H, or S-H proton quenches them (hence dry ether, flame-dried glassware). Grignard + formaldehyde -> 1° alcohol; + aldehyde -> 2°; + ketone -> 3°; + CO2 -> carboxylic acid; + epoxide -> extended alcohol. Victor Grignard's 1912 Nobel recognized the revolution.", "how": "Prepare in anhydrous ether under inert atmosphere; titrate if concentration matters. Add to the electrophile (carbonyl, epoxide, CO2) - never the reverse for reactive partners. Quench carefully with aqueous NH4Cl. Protect any acidic protons in the substrate first, or they will consume the reagent.", "keys": ["RMgX/RLi: carbon nucleophiles via umpolung.", "Destroyed by water, alcohols, acids - rigorously dry conditions.", "Carbonyl addition builds alcohols by class: 1°/2°/3°.", "CO2 gives acids; epoxides extend chains.", "Workup with aqueous NH4Cl protonates the alkoxide."], "reqs": ["Anhydrous ether solvent, inert atmosphere.", "No acidic protons in substrate.", "Halide precursor (Br/I best)."], "stds": ["Grignard formation in dry Et2O or THF.", "Quench protocol before aqueous workup."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Grignard V. C R Acad Sci 1900;130:1322."], "demo": "#!/usr/bin/env python3\n\"\"\"Grignard + carbonyl product class predictor.\"\"\"\ntable = {(\"RMgBr\", \"formaldehyde\"): \"primary alcohol\", (\"RMgBr\", \"aldehyde\"): \"secondary alcohol\", (\"RMgBr\", \"ketone\"): \"tertiary alcohol\", (\"RMgBr\", \"CO2\"): \"carboxylic acid\"}\nfor (rg, el), prod in table.items():\n    print(f\"  {rg} + {el:12s} -> {prod}\")\n"}, {"tier": "Advanced", "g": "Pericyclic", "title": "Diels-Alder Cycloaddition", "desc": "The Diels-Alder reaction - a [4+2] cycloaddition of a diene and a dienophile - builds two C-C bonds and a six-membered ring in one concerted step, with complete stereospecificity: cis dienophiles give cis products. It is the premier ring-forming reaction, run forward for synthesis and backward (retro) for analysis.\nThe endo rule: substituents on the dienophile orient under the diene pi system in the transition state, giving the endo product kinetically. Normal electron demand pairs electron-rich dienes with electron-poor dienophiles; Lewis acids catalyze by lowering the dienophile LUMO.", "how": "Draw the diene in s-cis conformation - s-trans cannot react. Align suprafacial-suprafacial overlap, assign endo stereochemistry to dienophile substituents, and transfer all stereochemistry from starting materials to product. Accelerate with Lewis acids (BF3, TiCl4) or use inverse-electron-demand variants for mismatched electronics.", "keys": ["[4+2] cycloaddition: diene + dienophile -> cyclohexene.", "Concerted and stereospecific - stereochemistry transfers fully.", "Endo rule governs substituent orientation.", "Diene must adopt s-cis conformation.", "Lewis acids catalyze via LUMO lowering."], "reqs": ["Diene capable of s-cis conformation.", "Electron-demand matching (normal or inverse).", "Endo/exo assignment in product."], "stds": ["Suprafacial-suprafacial orbital description.", "Endo rule stated for product prediction."], "cites": ["Diels O, Alder K. Liebigs Ann Chem 1928;460:98-122.", "McMurry J. Organic Chemistry. 10th ed. Cengage; 2023."], "demo": "#!/usr/bin/env python3\n\"\"\"Diels-Alder atom mapping: diene(4) + dienophile(2) -> ring(6).\"\"\"\ndiene_atoms, dienophile_atoms = 4, 2\nring = diene_atoms + dienophile_atoms\nprint(f\"  {diene_atoms} + {dienophile_atoms} -> {ring}-membered ring\")\nprint(\"  bonds formed: 2 C-C; pi bonds: 3 -> 1 (in ring) + 1 new pi\")\n"}, {"tier": "Advanced", "g": "Pericyclic", "title": "Pericyclic Reactions Overview", "desc": "Pericyclic reactions - electrocyclizations, cycloadditions, sigmatropic rearrangements - proceed through concerted cyclic transition states governed by orbital symmetry (Woodward-Hoffmann rules). The phase of p orbitals at the termini decides conrotatory vs disrotatory, suprafacial vs antarafacial.\nThermal reactions use ground-state HOMO symmetry; photochemical reactions use the excited state, inverting the selection rules. The Cope and Claisen rearrangements ([3,3]-sigmatropic) are workhorses; electrocyclization closes vitamin D's triene system in skin.", "how": "Count pi electrons: 4n thermal electrocyclization is conrotatory, 4n+2 is disrotatory; photochemical inverts this. For cycloadditions, check suprafacial-suprafacial feasibility with (4q+2) pi electrons thermally allowed. Draw the HOMO phases to verify bonding overlap at both termini.", "keys": ["Concerted cyclic transition states; no intermediates.", "Woodward-Hoffmann rules from orbital symmetry.", "Thermal vs photochemical selection rules invert.", "Electrocyclization, cycloaddition, sigmatropic = the three families.", "Stereochemistry is fully predictable from orbital phases."], "reqs": ["Pi-electron count and reaction family.", "Thermal vs photochemical conditions.", "Terminal orbital phase analysis."], "stds": ["Woodward-Hoffmann notation (e.g., pi4s + pi2s).", "Con/disrotatory labels for electrocyclizations."], "cites": ["Woodward RB, Hoffmann R. Angew Chem 1969;81:797-869.", "McMurry J. Organic Chemistry. 10th ed. Cengage; 2023."], "demo": "#!/usr/bin/env python3\n\"\"\"Electrocyclization mode predictor.\"\"\"\ndef mode(pi, hv=False):\n    thermal = \"conrotatory\" if pi % 4 == 0 else \"disrotatory\"\n    return {\"conrotatory\": \"disrotatory\", \"disrotatory\": \"conrotatory\"}[thermal] if hv else thermal\nfor pi in (4, 6):\n    print(f\"  {pi} pi e-: thermal {mode(pi)}, photochemical {mode(pi, True)}\")\n"}, {"tier": "Advanced", "g": "Synthesis", "title": "Retrosynthetic Analysis", "desc": "Retrosynthesis works backward from target to starting materials, breaking bonds into synthons - idealized fragments - and then into real reagents. E.J. Corey's formalism turned synthesis into a logical discipline: disconnect C-C bonds at strategic points, especially next to functional groups.\nGuidelines: disconnect where a known forward reaction forms the bond (aldol, Grignard, Diels-Alder); simplify stereochemistry and rings early; keep functional-group interconversions for late stages. Multiple routes are compared by step count, yield, and starting-material cost.", "how": "Identify strategic bonds - those formed by reliable reactions - and draw the disconnection with a squiggle. Convert synthons to synthetic equivalents (e.g., -CH2+ as alkyl halide). Iterate until reaching commercial starting materials, then write the forward scheme and check each step's compatibility with other functional groups present.", "keys": ["Work backward: target -> synthons -> reagents.", "Disconnect bonds made by reliable forward reactions.", "Synthons are idealized; equivalents are real reagents.", "Simplify rings and stereocenters early.", "Compare routes by steps, yield, and cost."], "reqs": ["Target structure with full stereochemistry.", "Catalog of reliable bond-forming reactions.", "Commercial starting-material pool."], "stds": ["Retrosynthetic arrow (=>) for disconnections.", "Synthon vs equivalent distinguished."], "cites": ["Corey EJ, Cheng XM. The Logic of Chemical Synthesis. Wiley; 1989.", "McMurry J. Organic Chemistry. 10th ed. Cengage; 2023."], "demo": "#!/usr/bin/env python3\n\"\"\"Retrosynthetic disconnection scorer (toy model).\"\"\"\nstrategies = {\"aldol disconnection\": 9, \"Diels-Alder disconnection\": 9, \"Grignard disconnection\": 8, \"random C-C cleavage\": 3}\nfor name, score in sorted(strategies.items(), key=lambda s: -s[1]):\n    print(f\"  {name:28s} reliability {score}/10\")\n"}, {"tier": "Advanced", "g": "Synthesis", "title": "Protecting Groups in Synthesis", "desc": "Complex synthesis requires doing chemistry at one site while others wait: protecting groups mask reactivity reversibly. Alcohols are protected as silyl ethers (TBS) or acetals; amines as Boc or Cbz carbamates; carbonyls as acetals; acids as esters.\nA good protecting group installs easily, survives the intervening steps, and removes cleanly under conditions orthogonal to everything else - TBS ethers fall to fluoride, Boc to acid, Cbz to hydrogenolysis. Each protection adds two steps, so the art is minimizing their use.", "how": "List all functional groups in the route and flag incompatibilities with planned reagents. Choose orthogonal sets - e.g., Boc (acid-labile) with TBS (fluoride-labile) - so each deprotects independently. Install early, remove late, and always ask whether the protection can be avoided by reordering steps.", "keys": ["Protecting groups mask reactivity reversibly.", "Orthogonality: each group removes under unique conditions.", "TBS (fluoride), Boc (acid), Cbz (H2/Pd) are the classics.", "Every protection costs two steps - minimize.", "Plan protection into the route, not as an afterthought."], "reqs": ["Full functional-group inventory of intermediates.", "Reagent compatibility matrix.", "Orthogonal deprotection conditions."], "stds": ["PG abbreviations per standard usage (Boc, Cbz, TBS).", "Deprotection conditions stated explicitly."], "cites": ["Wuts PGM, Greene TW. Protective Groups in Organic Synthesis. 5th ed. Wiley; 2014.", "McMurry J. Organic Chemistry. 10th ed. Cengage; 2023."], "demo": "#!/usr/bin/env python3\n\"\"\"Protecting-group orthogonality table.\"\"\"\npg = {\"TBS ether\": \"F- (TBAF)\", \"Boc amine\": \"acid (TFA)\", \"Cbz amine\": \"H2/Pd\", \"acetal\": \"aqueous acid\"}\nfor name, deprot in pg.items():\n    print(f\"  {name:12s} removed by {deprot}\")\n"}, {"tier": "Advanced", "g": "Biomolecules", "title": "Carbohydrates", "desc": "Carbohydrates are polyhydroxy aldehydes and ketones: glucose (an aldohexose) is the fuel of life, fructose a ketohexose. In solution they cyclize to hemiacetals - glucose is >99% cyclic - creating the anomeric center (alpha/beta) that defines glycosidic bonds.\nPolysaccharides are materials: starch and glycogen (alpha linkages) store energy; cellulose (beta linkages) builds plant walls - the most abundant organic compound on Earth. Glycosidic stereochemistry alone decides digestible vs indigestible.", "how": "Draw sugars in Fischer projection (D/L from the highest-numbered stereocenter) and convert to Haworth cyclic forms, assigning alpha/beta at the anomeric carbon. Form glycosides under acid catalysis; hydrolyze them with aqueous acid. Distinguish reducing sugars (free anomeric OH, Tollens positive) from non-reducing ones.", "keys": ["Glucose cyclizes to hemiacetals; alpha/beta anomers result.", "Glycosidic bond stereochemistry decides function.", "Starch/glycogen store energy; cellulose builds structure.", "D/L assigned from the highest-numbered stereocenter.", "Reducing sugars have a free anomeric OH."], "reqs": ["Fischer and Haworth representations.", "Anomeric configuration assigned.", "Glycosidic linkage positions."], "stds": ["D/L and alpha/beta notation per IUPAC.", "Haworth projections with correct stereochemistry."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Lindhorst TK. Essentials of Carbohydrate Chemistry. 4th ed. World Scientific; 2021."], "demo": "#!/usr/bin/env python3\n\"\"\"Carbohydrate classification helper.\"\"\"\nsugars = [(\"glucose\", \"aldohexose\"), (\"fructose\", \"ketohexose\"), (\"ribose\", \"aldopentose\"), (\"sucrose\", \"disaccharide\")]\nfor name, cls in sugars:\n    print(f\"  {name:9s}: {cls}\")\n"}, {"tier": "Advanced", "g": "Biomolecules", "title": "Amino Acids and Peptides", "desc": "Twenty standard amino acids build proteins, each with an amino group, carboxyl group, and side chain. At neutral pH they exist as zwitterions; side chains classify them as nonpolar, polar, acidic, or basic - the chemical alphabet of life.\nPeptide bonds (amides) link them, with partial double-bond character restricting rotation; the sequence is written N- to C-terminus. Solid-phase peptide synthesis (Merrifield, Nobel 1984) builds chains on resin with Boc/Fmoc protection cycles - automation that made synthetic peptides routine.", "how": "Write sequences N→C with three-letter codes. Predict charge from side-chain pKa values at a given pH (isoelectric point where net charge is zero). Synthesize with protection (Boc/Fmoc), DCC/HATU coupling, and deprotection cycles; cleave from resin with strong acid. Analyze by Edman degradation or mass spec.", "keys": ["20 standard amino acids; zwitterions at neutral pH.", "Side chains: nonpolar, polar, acidic, basic.", "Peptide bonds are planar amides; sequences run N→C.", "Solid-phase synthesis automates chain building.", "Charge predicted from side-chain pKa values."], "reqs": ["Amino-acid side-chain pKa table.", "N→C directionality maintained.", "Protection scheme for synthesis."], "stds": ["Three/one-letter codes per IUPAC.", "pI reported with calculation method."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Merrifield RB. J Am Chem Soc 1963;85:2149-2154."], "demo": "#!/usr/bin/env python3\n\"\"\"Net charge of a peptide fragment at pH 7 (toy model).\"\"\"\n# charges: N-term +1, C-term -1, Asp/Glu -1, Lys/Arg +1, His +0.1\nseq_charges = {\"Ala\": 0, \"Asp\": -1, \"Lys\": +1}\nseq = [\"Lys\", \"Ala\", \"Asp\"]\nnet = 1 - 1 + sum(seq_charges[a] for a in seq)\nprint(f\"  KAD at pH 7: net charge {net:+d}\")\n"}, {"tier": "Advanced", "g": "Biomolecules", "title": "Lipids and Membranes", "desc": "Lipids are defined by solubility - hydrophobic - not by a common functional group. Fatty acids (long carboxylic chains) form triglycerides for energy storage; saturation decides melting point (butter vs oil). Phospholipids build bilayers: hydrophilic heads out, hydrophobic tails in - the architecture of every cell membrane.\nSteroids (cholesterol, hormones) are rigid fused-ring systems modulating membrane fluidity and signaling. Saponification of triglycerides makes soap - amphiphiles that emulsify grease, known since Babylon.", "how": "Classify by structure: fatty acid/triglyceride, phospholipid, steroid, wax. Predict melting trends from chain length and unsaturation (cis double bonds kink chains, lowering mp). Draw bilayers with heads to water; make soap by base hydrolysis of fats and test emulsification.", "keys": ["Lipids defined by hydrophobicity, not one group.", "Saturation controls melting point.", "Phospholipid bilayers are membrane architecture.", "Steroids: rigid rings for signaling and structure.", "Saponification of fats yields soap."], "reqs": ["Fatty-acid chain length and unsaturation.", "Head-group identity for phospholipids.", "Aqueous environment for bilayer assembly."], "stds": ["Cis/trans and omega notation for fatty acids.", "Saponification value where relevant."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Gennis RB. Biomembranes. Springer; 1989."], "demo": "#!/usr/bin/env python3\n\"\"\"Fatty-acid melting trend vs unsaturation.\"\"\"\nfas = [(\"stearic 18:0\", 69), (\"oleic 18:1\", 13), (\"linoleic 18:2\", -5)]\nfor name, mp in fas:\n    print(f\"  {name:15s} mp {mp:4d} C\")\n"}, {"tier": "Advanced", "g": "Biomolecules", "title": "Polymers: Organic Synthesis of Macromolecules", "desc": "Polymers are giant molecules from repeating monomers: addition polymers (polyethylene from ethene, radical or Ziegler-Natta) and condensation polymers (nylon from diamine + diacid, PET from diol + diacid). Degree of polymerization and dispersity define the material.\nStructure controls properties: branching lowers crystallinity (LDPE vs HDPE), crosslinking makes thermosets (vulcanized rubber), and stereochemistry (isotactic polypropylene) tunes strength. Living polymerizations (ATRP, RAFT) give precise architectures - the modern synthetic frontier.", "how": "Choose addition for vinyl monomers (radical, cationic, anionic, or coordination) and condensation for difunctional pairs, removing water to drive molecular weight. Control branching with catalyst choice (Ziegler-Natta for linear HDPE). Characterize by GPC for molecular-weight distribution and DSC for thermal transitions.", "keys": ["Addition vs condensation: two polymerization families.", "Branching/crosslinking decide thermoplastic vs thermoset.", "Ziegler-Natta catalysts control stereochemistry.", "Living methods (ATRP/RAFT) give precise architectures.", "Dispersity measures molecular-weight spread."], "reqs": ["Monomer functionality (vinyl vs difunctional).", "Initiator/catalyst system.", "Molecular-weight characterization."], "stds": ["Mn, Mw, and dispersity reported.", "Tacticity notation for stereoregular polymers."], "cites": ["McMurry J. Organic Chemistry. 10th ed. Cengage; 2023.", "Odian G. Principles of Polymerization. 4th ed. Wiley; 2004."], "demo": "#!/usr/bin/env python3\n\"\"\"Degree of polymerization from masses.\"\"\"\nmonomer, polymer = 28.05, 280500  # ethene -> polyethylene\nprint(f\"  DP = {polymer/monomer:.0f} repeat units\")\n"}];
function buildRecord(seed,topic,sig){
  var title=topic.title+(sig?' (Signature Edition)':'');
  var desc=topic.desc;
  if(sig)desc='Signature original treatment. '+desc;
  return {
    id:(sig?'JAH-ORGCHS-':PREFIX)+String(seed).padStart(6,'0'),
    t:title, g:topic.g, name:title, title:title,
    description:desc,
    how_it_works:topic.how,
    key_points:topic.keys,
    requirements:topic.reqs,
    standards:topic.stds,
    citations:topic.cites,
    src:sig?'signature':'public-harvest',
    signature_label:sig?'Signature-generated original treatment - clearly labeled Signature-made and never presented as authentic public record.':'Public-harvest record - real, fact-checked domain knowledge.',
    ladder_rank:seed,
    ladder_tier:topic.tier.toLowerCase(),
    demo:{kind:'python',language:'python',program:topic.demo,
      note:'Working demonstration program for this record.'},
    _seed:seed
  };
}
function topicFor(seed,opts){
  opts=opts||{};
  var pool=TOPICS.filter(function(t){return !opts.field||t.tier===opts.field;});
  if(!pool.length)pool=TOPICS;
  var i=((seed-1)%pool.length+pool.length)%pool.length;
  return {topic:pool[i],index:TOPICS.indexOf(pool[i])};
}
function generate(seed,opts){
  var tf=topicFor(seed,opts);
  var sig=(opts&&opts.signature)||false;
  return buildRecord(tf.index+1,tf.topic,sig);
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return {ok:false,errors:['not an object']};
  var okId=new RegExp('^('+PREFIX.replace(/-/g,'\\-')+'|'+'JAH-ORGCHS-'.replace(/-/g,'\\-')+')\\d{6}$').test(r.id||'');
  if(!okId)e.push('id');
  if(FIELDS.indexOf(capTier(r.ladder_tier))<0)e.push('tier');
  if(['public-harvest','signature'].indexOf(r.src)<0)e.push('src');
  if(!r.title)e.push('title');
  if(!r.description||r.description.length<40)e.push('description');
  if(!r.demo||!r.demo.program||r.demo.program.indexOf('print')<0)e.push('demo');
  return {ok:!e.length,errors:e};
}
function capTier(s){s=String(s||'');return s.charAt(0).toUpperCase()+s.slice(1);}
function driftCheck(record,sample){
  var dups=(sample||[]).filter(function(r){return r&&r.title===record.title&&r.ladder_tier===record.ladder_tier;});
  return dups.length?{ok:false,errors:['duplicate title+tier in archive sample']}:{ok:true,errors:[]};
}
var gen={version:'jahdb-organic-chemistry-1.0',generate:generate,validate:validate,driftCheck:driftCheck,fields:FIELDS};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('organic-chemistry',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();
